"use client"

import { useQuery } from "@tanstack/react-query"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { FileText } from "lucide-react"
import { fetchConsolidatedIncome } from "@/lib/api"

function StatementRow({
  label,
  amount,
  variant = "normal",
}: {
  label: string
  amount?: string
  variant?: "normal" | "indent" | "subtitle" | "total" | "grand-total"
}) {
  const baseStyles = "flex justify-between py-3 px-4 border-b border-border"
  const variantStyles = {
    normal: "",
    indent: "pl-10 text-muted-foreground",
    subtitle: "font-semibold text-primary bg-secondary mt-2",
    total: "font-semibold bg-secondary border-t-2 border-b-2 border-border mt-2",
    "grand-total": "bg-primary text-primary-foreground font-semibold text-lg mt-4",
  }

  return (
    <div className={`${baseStyles} ${variantStyles[variant]}`}>
      <span>{label}</span>
      {amount && (
        <span className="font-serif font-semibold tabular-nums">{amount}</span>
      )}
    </div>
  )
}

export function ConsolidatedIncome() {
  const { data, isLoading } = useQuery({
    queryKey: ["consolidated-income"],
    queryFn: fetchConsolidatedIncome,
  })

  if (isLoading) {
    return (
      <div className="text-center py-12 text-muted-foreground">
        Loading income statement...
      </div>
    )
  }

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between">
        <div>
          <CardTitle className="font-serif">IREBE Group - Consolidated Income Statement</CardTitle>
          <p className="text-sm text-muted-foreground mt-1 italic">
            For the Quarter Ending 31 March 2026
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline">Change Period</Button>
          <Button className="bg-accent text-accent-foreground hover:bg-accent/90">
            <FileText className="h-4 w-4 mr-2" />
            Export PDF
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        <div className="space-y-6">
          <div>
            <h3 className="text-lg font-serif font-semibold text-primary border-b-2 border-primary pb-2 mb-4">
              Revenue by Company
            </h3>
            <StatementRow label="IREBE Construction Ltd" amount="RWF 320,000,000" variant="indent" />
            <StatementRow label="IREBE Trading Ltd" amount="RWF 580,000,000" variant="indent" />
            <StatementRow label="IREBE Logistics Ltd" amount="RWF 240,000,000" variant="indent" />
            <StatementRow label="IREBE Tech Solutions Ltd" amount="RWF 185,000,000" variant="indent" />
            <StatementRow label="Total Group Revenue" amount="RWF 1,325,000,000" variant="total" />
          </div>

          <div>
            <h3 className="text-lg font-serif font-semibold text-primary border-b-2 border-primary pb-2 mb-4">
              Operating Expenses
            </h3>
            <StatementRow label="Total Salaries & Wages" amount="RWF 420,000,000" variant="indent" />
            <StatementRow label="Materials & Supplies" amount="RWF 180,000,000" variant="indent" />
            <StatementRow label="Transport & Logistics" amount="RWF 95,000,000" variant="indent" />
            <StatementRow label="Rent & Utilities" amount="RWF 65,000,000" variant="indent" />
            <StatementRow label="Marketing & Admin" amount="RWF 45,000,000" variant="indent" />
            <StatementRow label="Other Operating Expenses" amount="RWF 85,000,000" variant="indent" />
            <StatementRow label="Total Operating Expenses" amount="RWF 890,000,000" variant="total" />
          </div>

          <StatementRow label="Net Group Profit" amount="RWF 435,000,000" variant="grand-total" />
        </div>
      </CardContent>
    </Card>
  )
}
