"use client"

import React from "react"

import { useState } from "react"
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Badge } from "@/components/ui/badge"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  Plus,
  ChevronRight,
  ChevronDown,
  FolderTree,
  Layers,
  Tag,
  Loader2,
} from "lucide-react"
import { cn } from "@/lib/utils"
import {
  fetchMainCategories,
  fetchSubCategories,
  fetchSubSubCategories,
  createCategory,
  type Category,
  type CategoryLevel,
  type CategoryType,
  type CreateCategoryDto,
} from "@/lib/api"

const categoryTypeColors: Record<string, string> = {
  asset: "bg-blue-100 text-blue-800 border-blue-200",
  liability: "bg-red-100 text-red-800 border-red-200",
  equity: "bg-green-100 text-green-800 border-green-200",
  income: "bg-emerald-100 text-emerald-800 border-emerald-200",
  expense: "bg-orange-100 text-orange-800 border-orange-200",
}

const categoryLevelIcons: Record<CategoryLevel, React.ReactNode> = {
  main: <FolderTree className="h-4 w-4" />,
  sub: <Layers className="h-4 w-4" />,
  sub_sub: <Tag className="h-4 w-4" />,
}

function CategoryItem({
  category,
  level = 0,
}: {
  category: Category
  level?: number
}) {
  const [isOpen, setIsOpen] = useState(false)
  const [subCategories, setSubCategories] = useState<Category[]>([])
  const [isLoadingSubs, setIsLoadingSubs] = useState(false)

  const handleToggle = async () => {
    if (!isOpen && subCategories.length === 0 && category.level !== "sub_sub") {
      setIsLoadingSubs(true)
      try {
        const subs =
          category.level === "main"
            ? await fetchSubCategories(category.id)
            : await fetchSubSubCategories(category.id)
        setSubCategories(subs)
      } catch (error) {
        console.error("Error loading sub-categories:", error)
      } finally {
        setIsLoadingSubs(false)
      }
    }
    setIsOpen(!isOpen)
  }

  const hasChildren = category.level !== "sub_sub"

  return (
    <div>
      <Collapsible open={isOpen} onOpenChange={handleToggle}>
        <CollapsibleTrigger asChild>
          <button
            className={cn(
              "w-full flex items-center gap-3 px-4 py-3 text-left hover:bg-muted/50 transition-colors rounded-lg",
              level > 0 && "ml-6"
            )}
          >
            {hasChildren ? (
              isOpen ? (
                <ChevronDown className="h-4 w-4 text-muted-foreground flex-shrink-0" />
              ) : (
                <ChevronRight className="h-4 w-4 text-muted-foreground flex-shrink-0" />
              )
            ) : (
              <span className="w-4" />
            )}
            <span className="flex-shrink-0">
              {categoryLevelIcons[category.level]}
            </span>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                {category.code && (
                  <span className="text-xs font-mono text-muted-foreground">
                    {category.code}
                  </span>
                )}
                <span className="font-medium truncate">{category.name}</span>
              </div>
              {category.description && (
                <p className="text-xs text-muted-foreground truncate">
                  {category.description}
                </p>
              )}
            </div>
            <div className="flex items-center gap-2 flex-shrink-0">
              {category.categoryType && (
                <Badge
                  variant="outline"
                  className={cn(
                    "capitalize text-xs",
                    categoryTypeColors[category.categoryType]
                  )}
                >
                  {category.categoryType}
                </Badge>
              )}
              <Badge
                variant="outline"
                className={cn(
                  "text-xs",
                  category.isActive
                    ? "bg-green-50 text-green-700 border-green-200"
                    : "bg-gray-50 text-gray-500 border-gray-200"
                )}
              >
                {category.isActive ? "Active" : "Inactive"}
              </Badge>
              {category.allowTransactions && (
                <Badge
                  variant="outline"
                  className="text-xs bg-purple-50 text-purple-700 border-purple-200"
                >
                  Transactional
                </Badge>
              )}
            </div>
          </button>
        </CollapsibleTrigger>
        {hasChildren && (
          <CollapsibleContent>
            {isLoadingSubs ? (
              <div className="ml-10 py-2 flex items-center gap-2 text-muted-foreground">
                <Loader2 className="h-4 w-4 animate-spin" />
                <span className="text-sm">Loading...</span>
              </div>
            ) : subCategories.length > 0 ? (
              <div className="border-l-2 border-muted ml-6">
                {subCategories.map((sub) => (
                  <CategoryItem key={sub.id} category={sub} level={level + 1} />
                ))}
              </div>
            ) : (
              <div className="ml-10 py-2 text-sm text-muted-foreground">
                No sub-categories
              </div>
            )}
          </CollapsibleContent>
        )}
      </Collapsible>
    </div>
  )
}

function CreateCategoryDialog() {
  const queryClient = useQueryClient()
  const [open, setOpen] = useState(false)
  const [formData, setFormData] = useState<CreateCategoryDto>({
    code: "",
    name: "",
    description: "",
    level: "main",
    categoryType: null,
    sortOrder: 0,
  })

  const { data: mainCategories } = useQuery({
    queryKey: ["categories", "main"],
    queryFn: fetchMainCategories,
  })

  const [selectedMainId, setSelectedMainId] = useState<number | null>(null)
  const { data: subCategories } = useQuery({
    queryKey: ["categories", "sub", selectedMainId],
    queryFn: () => (selectedMainId ? fetchSubCategories(selectedMainId) : Promise.resolve([])),
    enabled: !!selectedMainId && formData.level === "sub_sub",
  })

  const createMutation = useMutation({
    mutationFn: createCategory,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["categories"] })
      setOpen(false)
      setFormData({
        code: "",
        name: "",
        description: "",
        level: "main",
        categoryType: null,
        sortOrder: 0,
      })
      setSelectedMainId(null)
    },
  })

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    createMutation.mutate(formData)
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button>
          <Plus className="h-4 w-4 mr-2" />
          Add Category
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>Create New Category</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="level">Level</Label>
              <Select
                value={formData.level}
                onValueChange={(value) => {
                  setFormData({ ...formData, level: value as CategoryLevel, parentId: undefined })
                  setSelectedMainId(null)
                }}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select level" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="main">Main Category</SelectItem>
                  <SelectItem value="sub">Sub Category</SelectItem>
                  <SelectItem value="sub_sub">Sub-Sub Category</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="categoryType">Category Type</Label>
              <Select
                value={formData.categoryType || ""}
                onValueChange={(value) =>
                  setFormData({ ...formData, categoryType: (value || null) as CategoryType })
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="asset">Asset</SelectItem>
                  <SelectItem value="liability">Liability</SelectItem>
                  <SelectItem value="equity">Equity</SelectItem>
                  <SelectItem value="income">Income</SelectItem>
                  <SelectItem value="expense">Expense</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {formData.level !== "main" && (
            <div className="space-y-2">
              <Label>Parent Main Category</Label>
              <Select
                value={selectedMainId?.toString() || ""}
                onValueChange={(value) => {
                  const id = parseInt(value)
                  setSelectedMainId(id)
                  if (formData.level === "sub") {
                    setFormData({ ...formData, parentId: id })
                  }
                }}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select main category" />
                </SelectTrigger>
                <SelectContent>
                  {mainCategories?.map((cat) => (
                    <SelectItem key={cat.id} value={cat.id.toString()}>
                      {cat.code ? `${cat.code} - ` : ""}{cat.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {formData.level === "sub_sub" && selectedMainId && (
            <div className="space-y-2">
              <Label>Parent Sub Category</Label>
              <Select
                value={formData.parentId?.toString() || ""}
                onValueChange={(value) =>
                  setFormData({ ...formData, parentId: parseInt(value) })
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select sub category" />
                </SelectTrigger>
                <SelectContent>
                  {subCategories?.map((cat) => (
                    <SelectItem key={cat.id} value={cat.id.toString()}>
                      {cat.code ? `${cat.code} - ` : ""}{cat.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="code">Code</Label>
              <Input
                id="code"
                value={formData.code}
                onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                placeholder="e.g., 101"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="sortOrder">Sort Order</Label>
              <Input
                id="sortOrder"
                type="number"
                value={formData.sortOrder}
                onChange={(e) =>
                  setFormData({ ...formData, sortOrder: parseInt(e.target.value) || 0 })
                }
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="name">Name</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              placeholder="Category name"
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              placeholder="Optional description"
              rows={2}
            />
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <Button type="button" variant="outline" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={createMutation.isPending}>
              {createMutation.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Create Category
            </Button>
          </div>

          {createMutation.isError && (
            <p className="text-sm text-destructive">
              {createMutation.error instanceof Error
                ? createMutation.error.message
                : "Failed to create category"}
            </p>
          )}
        </form>
      </DialogContent>
    </Dialog>
  )
}

export function CategoryManagement() {
  const {
    data: mainCategories,
    isLoading,
    error,
  } = useQuery({
    queryKey: ["categories", "main"],
    queryFn: fetchMainCategories,
  })

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-lg font-semibold">Account Categories</h2>
          <p className="text-sm text-muted-foreground">
            Manage your chart of accounts hierarchy
          </p>
        </div>
        <CreateCategoryDialog />
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-primary/10 rounded-lg">
                <FolderTree className="h-5 w-5 text-primary" />
              </div>
              <div>
                <p className="text-2xl font-bold">{mainCategories?.length || 0}</p>
                <p className="text-xs text-muted-foreground">Main Categories</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-blue-100 rounded-lg">
                <Tag className="h-5 w-5 text-blue-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">
                  {mainCategories?.filter((c) => c.categoryType === "asset").length || 0}
                </p>
                <p className="text-xs text-muted-foreground">Asset Categories</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-emerald-100 rounded-lg">
                <Tag className="h-5 w-5 text-emerald-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">
                  {mainCategories?.filter((c) => c.categoryType === "income").length || 0}
                </p>
                <p className="text-xs text-muted-foreground">Income Categories</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-orange-100 rounded-lg">
                <Tag className="h-5 w-5 text-orange-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">
                  {mainCategories?.filter((c) => c.categoryType === "expense").length || 0}
                </p>
                <p className="text-xs text-muted-foreground">Expense Categories</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Category Tree */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">Category Hierarchy</CardTitle>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : error ? (
            <div className="text-center py-12 text-destructive">
              <p>Failed to load categories</p>
              <p className="text-sm text-muted-foreground mt-1">
                {error instanceof Error ? error.message : "Unknown error"}
              </p>
            </div>
          ) : mainCategories && mainCategories.length > 0 ? (
            <div className="divide-y">
              {mainCategories.map((category) => (
                <CategoryItem key={category.id} category={category} />
              ))}
            </div>
          ) : (
            <div className="text-center py-12 text-muted-foreground">
              <FolderTree className="h-12 w-12 mx-auto mb-4 opacity-50" />
              <p>No categories found</p>
              <p className="text-sm">Create your first category to get started</p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}
