"use client"

import React, { useState } from "react"
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from "@/components/ui/select"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { 
  CheckCircle2, 
  AlertCircle, 
  Plus, 
  Search,
  Calendar,
  DollarSign,
  TrendingUp,
  TrendingDown,
  Repeat,
  FileText,
  Filter
} from "lucide-react"
import { format } from "date-fns"

// ============================================================================
// TYPE DEFINITIONS (matching actual API response)
// ============================================================================

export enum TransactionType {
  DEBIT = 'debit',
  CREDIT = 'credit',
}

export enum TransactionStatus {
  PENDING = 'pending',
  COMPLETED = 'completed',
  RECONCILED = 'reconciled',
  CANCELLED = 'cancelled',
}

export enum PaymentMethod {
  CASH = 'cash',
  BANK_TRANSFER = 'bank_transfer',
  CHEQUE = 'cheque',
  MOBILE_MONEY = 'mobile_money',
  CREDIT_CARD = 'credit_card',
  DEBIT_CARD = 'debit_card',
  OTHER = 'other',
}

interface CategoryParent {
  id: number
  code: string | null
  name: string
  level: string
  categoryType: string | null
  parent?: CategoryParent
}

interface TransactionCategory {
  id: number
  code: string | null
  name: string
  description: string | null
  level: string
  categoryType: string | null
  sortOrder: number
  isActive: boolean
  allowTransactions: boolean
  parent?: CategoryParent
}

interface TransactionCompany {
  id: number
  name: string
  description: string | null
  email: string
  isActive: boolean
}

interface TransactionCreator {
  id: number
  name: string
  email: string
  role: string
  profile?: {
    id: number
    gender: string | null
    position: string | null
  }
}

interface TransactionCreator {
  id: number
  name: string
  email: string
  role: string
  profile?: {
    id: number
    gender: string | null
    position: string | null
  }
}

interface Transaction {
  id: number
  date: string
  transactionType: TransactionType
  amount: string
  description: string
  referenceNumber: string | null
  paymentMethod: PaymentMethod
  status: TransactionStatus
  counterparty: string | null
  invoiceNumber: string | null
  dueDate: string | null
  taxAmount: string
  taxRate: string
  totalAmount: string
  reconciledAt: string | null
  notes: string | null
  attachments: string[] | null
  isRecurring: boolean
  recurringFrequency: string | null
  financialYear: number
  financialPeriod: number
  createdAt: string
  updatedAt: string
  deletedAt: string | null
  company: TransactionCompany
  category: TransactionCategory
  createdBy: TransactionCreator
  categoryPath: string
}

interface LeafCategory {
  id: number
  name: string
  code: string | null
  categoryType: string | null
  level: string
  allowTransactions: boolean
  parent?: {
    id: number
    name: string
    parent?: {
      id: number
      name: string
    }
  }
}

interface CreateTransactionDto {
  companyId: number
  date: string
  transactionType: TransactionType
  amount: number
  description: string
  categoryId: number
  referenceNumber?: string
  paymentMethod?: PaymentMethod
  status?: TransactionStatus
  counterparty?: string
  invoiceNumber?: string
  dueDate?: string
  taxRate?: number
  taxAmount?: number
  notes?: string
  attachments?: string[]
  isRecurring?: boolean
  recurringFrequency?: string
  createdBy: number
}

// ============================================================================
// API FUNCTIONS
// ============================================================================

const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL || ""

async function createTransaction(data: CreateTransactionDto): Promise<any> {
  const response = await fetch(`${API_BASE_URL}/transactions`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(data),
  })
  if (!response.ok) {
    const error = await response.json()
    throw new Error(error.message || "Failed to create transaction")
  }
  return response.json()
}

async function fetchTransactions(companyId?: number): Promise<Transaction[]> {
  const url = companyId 
    ? `${API_BASE_URL}/transactions/company/${companyId}`
    : `${API_BASE_URL}/transactions`
  
  const response = await fetch(url)
  if (!response.ok) throw new Error("Failed to fetch transactions")
  const data = await response.json()
  return data.transactions || []
}

async function fetchLeafCategories(): Promise<LeafCategory[]> {
  const response = await fetch(`${API_BASE_URL}/categories/leaf`)
  if (!response.ok) throw new Error("Failed to fetch categories")
  return response.json()
}

async function fetchCompanies(): Promise<any[]> {
  const response = await fetch(`${API_BASE_URL}/company`)
  if (!response.ok) throw new Error("Failed to fetch companies")
  const data = await response.json()
  return data.companies || []
}

async function executeRecurringTransaction(id: number): Promise<any> {
  const response = await fetch(`${API_BASE_URL}/transactions/recurring/${id}/execute`, {
    method: "POST",
  })
  if (!response.ok) throw new Error("Failed to execute recurring transaction")
  return response.json()
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export function TransactionManagement() {
  const queryClient = useQueryClient()
  const [activeTab, setActiveTab] = useState("create")
  const [selectedCompany, setSelectedCompany] = useState<number | undefined>()
  const [success, setSuccess] = useState(false)
  const [errorMsg, setErrorMsg] = useState("")

  // Form state
  const [formData, setFormData] = useState<Partial<CreateTransactionDto>>({
    companyId: undefined,
    date: format(new Date(), "yyyy-MM-dd"),
    transactionType: TransactionType.DEBIT,
    amount: 0,
    description: "",
    categoryId: undefined,
    paymentMethod: PaymentMethod.CASH,
    status: TransactionStatus.COMPLETED,
    createdBy: 1, // TODO: Get from auth context
  })

  // Queries
  const { data: companies = [] } = useQuery({
    queryKey: ["companies"],
    queryFn: fetchCompanies,
  })

  const { data: categories = [] } = useQuery({
    queryKey: ["leaf-categories"],
    queryFn: fetchLeafCategories,
  })

  const { data: transactions = [], isLoading: transactionsLoading } = useQuery({
    queryKey: ["transactions", selectedCompany],
    queryFn: () => fetchTransactions(selectedCompany),
  })

  // Mutations
  const createMutation = useMutation({
    mutationFn: createTransaction,
    onSuccess: () => {
      setSuccess(true)
      setErrorMsg("")
      resetForm()
      queryClient.invalidateQueries({ queryKey: ["transactions"] })
      queryClient.invalidateQueries({ queryKey: ["dashboard-stats"] })
      setTimeout(() => setSuccess(false), 5000)
    },
    onError: (error: Error) => {
      setErrorMsg(error.message)
      setSuccess(false)
    },
  })

  const executeMutation = useMutation({
    mutationFn: executeRecurringTransaction,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["transactions"] })
    },
  })

  // Handlers
  const resetForm = () => {
    setFormData({
      companyId: undefined,
      date: format(new Date(), "yyyy-MM-dd"),
      transactionType: TransactionType.DEBIT,
      amount: 0,
      description: "",
      categoryId: undefined,
      paymentMethod: PaymentMethod.CASH,
      status: TransactionStatus.COMPLETED,
      createdBy: 1,
    })
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    setErrorMsg("")

    // Validation
    if (!formData.companyId) {
      setErrorMsg("Please select a company")
      return
    }
    if (!formData.categoryId) {
      setErrorMsg("Please select a category")
      return
    }
    if (!formData.amount || formData.amount <= 0) {
      setErrorMsg("Please enter a valid amount")
      return
    }
    if (!formData.description?.trim()) {
      setErrorMsg("Please enter a description")
      return
    }

    createMutation.mutate(formData as CreateTransactionDto)
  }

  const updateField = (field: keyof CreateTransactionDto, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }))
  }

  // Calculate tax
  const calculateTax = () => {
    if (formData.taxRate && formData.amount) {
      const tax = (formData.amount * formData.taxRate) / 100
      updateField("taxAmount", tax)
    }
  }

  // Group categories by type for better organization
  const categoriesByType = React.useMemo(() => {
    const grouped: Record<string, LeafCategory[]> = {}
    
    categories.forEach(cat => {
      if (!cat.allowTransactions) return // Skip non-transaction categories
      
      const type = cat.categoryType || "other"
      if (!grouped[type]) grouped[type] = []
      grouped[type].push(cat)
    })
    
    return grouped
  }, [categories])

  // Get category display name with full path
  const getCategoryDisplayName = (category: LeafCategory) => {
    const parts: string[] = []
    if (category.parent?.parent?.name) parts.push(category.parent.parent.name)
    if (category.parent?.name) parts.push(category.parent.name)
    parts.push(category.name)
    return parts.join(" > ")
  }

  // Filter transactions
  const recurringTransactions = transactions.filter(t => t.isRecurring)
  const regularTransactions = transactions.filter(t => !t.isRecurring)

  // Stats
  const totalIncome = transactions
    .filter(t => t.transactionType === TransactionType.DEBIT)
    .reduce((sum, t) => sum + Number(t.totalAmount), 0)
  
  const totalExpenses = transactions
    .filter(t => t.transactionType === TransactionType.CREDIT)
    .reduce((sum, t) => sum + Number(t.totalAmount), 0)

  return (
    <div className="space-y-6">
      {/* Header Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Total Income</p>
                <p className="text-2xl font-bold text-green-600">
                  RWF {totalIncome.toLocaleString()}
                </p>
              </div>
              <TrendingUp className="h-8 w-8 text-green-600" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Total Expenses</p>
                <p className="text-2xl font-bold text-red-600">
                  RWF {totalExpenses.toLocaleString()}
                </p>
              </div>
              <TrendingDown className="h-8 w-8 text-red-600" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Net Position</p>
                <p className={`text-2xl font-bold ${totalIncome - totalExpenses >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                  RWF {(totalIncome - totalExpenses).toLocaleString()}
                </p>
              </div>
              <DollarSign className="h-8 w-8 text-primary" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Main Content */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid w-full grid-cols-3">
          <TabsTrigger value="create">
            <Plus className="h-4 w-4 mr-2" />
            Create Transaction
          </TabsTrigger>
          <TabsTrigger value="list">
            <FileText className="h-4 w-4 mr-2" />
            All Transactions
          </TabsTrigger>
          <TabsTrigger value="recurring">
            <Repeat className="h-4 w-4 mr-2" />
            Recurring
          </TabsTrigger>
        </TabsList>

        {/* CREATE TRANSACTION TAB */}
        <TabsContent value="create">
          <Card>
            <CardHeader>
              <CardTitle>Record New Transaction</CardTitle>
            </CardHeader>
            <CardContent>
              {success && (
                <Alert className="mb-6 bg-green-50 border-green-200 text-green-800">
                  <CheckCircle2 className="h-4 w-4" />
                  <AlertDescription>
                    Transaction recorded successfully!
                  </AlertDescription>
                </Alert>
              )}

              {errorMsg && (
                <Alert className="mb-6 bg-red-50 border-red-200 text-red-800">
                  <AlertCircle className="h-4 w-4" />
                  <AlertDescription>{errorMsg}</AlertDescription>
                </Alert>
              )}

              <form onSubmit={handleSubmit} className="space-y-6">
                {/* Basic Information */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="company">
                      Company <span className="text-red-500">*</span>
                    </Label>
                    <Select
                      value={formData.companyId?.toString()}
                      onValueChange={(value) => updateField("companyId", parseInt(value))}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select company" />
                      </SelectTrigger>
                      <SelectContent>
                        {companies.map((company) => (
                          <SelectItem key={company.id} value={company.id.toString()}>
                            {company.name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="date">
                      Date <span className="text-red-500">*</span>
                    </Label>
                    <Input
                      id="date"
                      type="date"
                      value={formData.date}
                      onChange={(e) => updateField("date", e.target.value)}
                      required
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="transactionType">
                      Type <span className="text-red-500">*</span>
                    </Label>
                    <Select
                      value={formData.transactionType}
                      onValueChange={(value) => updateField("transactionType", value)}
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value={TransactionType.DEBIT}>
                          Income (Debit)
                        </SelectItem>
                        <SelectItem value={TransactionType.CREDIT}>
                          Expense (Credit)
                        </SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="category">
                      Category <span className="text-red-500">*</span>
                    </Label>
                    <Select
                      value={formData.categoryId?.toString()}
                      onValueChange={(value) => updateField("categoryId", parseInt(value))}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select category" />
                      </SelectTrigger>
                      <SelectContent className="max-h-[300px]">
                        {Object.entries(categoriesByType).map(([type, cats]) => (
                          <React.Fragment key={type}>
                            <div className="px-2 py-1.5 text-xs font-semibold text-muted-foreground uppercase bg-muted/50">
                              {type.replace('_', ' ')}
                            </div>
                            {cats.map((cat) => (
                              <SelectItem key={cat.id} value={cat.id.toString()}>
                                <span className="text-xs text-muted-foreground mr-2">{cat.code}</span>
                                {getCategoryDisplayName(cat)}
                              </SelectItem>
                            ))}
                          </React.Fragment>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="amount">
                      Amount (RWF) <span className="text-red-500">*</span>
                    </Label>
                    <Input
                      id="amount"
                      type="number"
                      step="0.01"
                      min="0"
                      value={formData.amount || ""}
                      onChange={(e) => updateField("amount", parseFloat(e.target.value))}
                      required
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="paymentMethod">Payment Method</Label>
                    <Select
                      value={formData.paymentMethod}
                      onValueChange={(value) => updateField("paymentMethod", value)}
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value={PaymentMethod.CASH}>Cash</SelectItem>
                        <SelectItem value={PaymentMethod.BANK_TRANSFER}>Bank Transfer</SelectItem>
                        <SelectItem value={PaymentMethod.MOBILE_MONEY}>Mobile Money</SelectItem>
                        <SelectItem value={PaymentMethod.CHEQUE}>Cheque</SelectItem>
                        <SelectItem value={PaymentMethod.CREDIT_CARD}>Credit Card</SelectItem>
                        <SelectItem value={PaymentMethod.DEBIT_CARD}>Debit Card</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                {/* Additional Details */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="referenceNumber">Reference Number</Label>
                    <Input
                      id="referenceNumber"
                      placeholder="e.g., INV-2026-001"
                      value={formData.referenceNumber || ""}
                      onChange={(e) => updateField("referenceNumber", e.target.value)}
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="counterparty">Counterparty</Label>
                    <Input
                      id="counterparty"
                      placeholder="Customer/Supplier name"
                      value={formData.counterparty || ""}
                      onChange={(e) => updateField("counterparty", e.target.value)}
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="invoiceNumber">Invoice Number</Label>
                    <Input
                      id="invoiceNumber"
                      placeholder="Invoice #"
                      value={formData.invoiceNumber || ""}
                      onChange={(e) => updateField("invoiceNumber", e.target.value)}
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="taxRate">Tax Rate (%)</Label>
                    <Input
                      id="taxRate"
                      type="number"
                      step="0.01"
                      min="0"
                      max="100"
                      value={formData.taxRate || ""}
                      onChange={(e) => {
                        updateField("taxRate", parseFloat(e.target.value))
                        setTimeout(calculateTax, 0)
                      }}
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="taxAmount">Tax Amount (Auto)</Label>
                    <Input
                      id="taxAmount"
                      type="number"
                      value={formData.taxAmount || ""}
                      disabled
                      className="bg-muted"
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="status">Status</Label>
                    <Select
                      value={formData.status}
                      onValueChange={(value) => updateField("status", value)}
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value={TransactionStatus.PENDING}>Pending</SelectItem>
                        <SelectItem value={TransactionStatus.COMPLETED}>Completed</SelectItem>
                        <SelectItem value={TransactionStatus.RECONCILED}>Reconciled</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                {/* Description & Notes */}
                <div className="space-y-2">
                  <Label htmlFor="description">
                    Description <span className="text-red-500">*</span>
                  </Label>
                  <Textarea
                    id="description"
                    placeholder="Enter transaction description"
                    value={formData.description}
                    onChange={(e) => updateField("description", e.target.value)}
                    required
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="notes">Additional Notes</Label>
                  <Textarea
                    id="notes"
                    placeholder="Optional notes"
                    value={formData.notes || ""}
                    onChange={(e) => updateField("notes", e.target.value)}
                  />
                </div>

                {/* Recurring Options */}
                <div className="flex items-center space-x-4">
                  <input
                    type="checkbox"
                    id="isRecurring"
                    checked={formData.isRecurring || false}
                    onChange={(e) => updateField("isRecurring", e.target.checked)}
                    className="h-4 w-4"
                  />
                  <Label htmlFor="isRecurring" className="cursor-pointer">
                    Make this a recurring transaction
                  </Label>
                </div>

                {formData.isRecurring && (
                  <div className="space-y-2">
                    <Label htmlFor="recurringFrequency">Frequency</Label>
                    <Select
                      value={formData.recurringFrequency}
                      onValueChange={(value) => updateField("recurringFrequency", value)}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select frequency" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="daily">Daily</SelectItem>
                        <SelectItem value="weekly">Weekly</SelectItem>
                        <SelectItem value="monthly">Monthly</SelectItem>
                        <SelectItem value="quarterly">Quarterly</SelectItem>
                        <SelectItem value="yearly">Yearly</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                )}

                {/* Action Buttons */}
                <div className="flex gap-4">
                  <Button
                    type="submit"
                    disabled={createMutation.isPending}
                  >
                    {createMutation.isPending ? "Recording..." : "Record Transaction"}
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    onClick={resetForm}
                  >
                    Clear Form
                  </Button>
                </div>
              </form>
            </CardContent>
          </Card>
        </TabsContent>

        {/* TRANSACTIONS LIST TAB */}
        <TabsContent value="list">
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle>All Transactions</CardTitle>
                <Select
                  value={selectedCompany?.toString() || "all"}
                  onValueChange={(value) => setSelectedCompany(value === "all" ? undefined : parseInt(value))}
                >
                  <SelectTrigger className="w-[200px]">
                    <SelectValue placeholder="Filter by company" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Companies</SelectItem>
                    {companies.map((company) => (
                      <SelectItem key={company.id} value={company.id.toString()}>
                        {company.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </CardHeader>
            <CardContent>
              {transactionsLoading ? (
                <p className="text-center py-8 text-muted-foreground">Loading transactions...</p>
              ) : regularTransactions.length === 0 ? (
                <p className="text-center py-8 text-muted-foreground">No transactions found</p>
              ) : (
                <div className="space-y-4">
                  {regularTransactions.map((transaction) => (
                    <div
                      key={transaction.id}
                      className="p-4 border rounded-lg hover:bg-muted/50 transition-colors"
                    >
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                            <Badge variant={transaction.transactionType === TransactionType.DEBIT ? "default" : "destructive"}>
                              {transaction.transactionType === TransactionType.DEBIT ? "Income" : "Expense"}
                            </Badge>
                            <Badge variant="outline">{transaction.status}</Badge>
                            {transaction.company?.name && (
                              <span className="text-sm text-muted-foreground">{transaction.company.name}</span>
                            )}
                          </div>
                          <h4 className="font-medium">{transaction.description}</h4>
                          <p className="text-sm text-muted-foreground mt-1">
                            {transaction.categoryPath}
                          </p>
                          {transaction.category?.code && (
                            <p className="text-xs text-muted-foreground">
                              Code: {transaction.category.code}
                            </p>
                          )}
                          <div className="flex items-center gap-4 mt-2 text-sm text-muted-foreground">
                            <span className="flex items-center gap-1">
                              <Calendar className="h-3 w-3" />
                              {format(new Date(transaction.date), "MMM dd, yyyy")}
                            </span>
                            {transaction.counterparty && (
                              <span>{transaction.counterparty}</span>
                            )}
                            {transaction.referenceNumber && (
                              <span>Ref: {transaction.referenceNumber}</span>
                            )}
                          </div>
                          {transaction.notes && (
                            <p className="text-xs text-muted-foreground mt-2">
                              Note: {transaction.notes}
                            </p>
                          )}
                        </div>
                        <div className="text-right">
                          <p className={`text-lg font-bold ${transaction.transactionType === TransactionType.DEBIT ? 'text-green-600' : 'text-red-600'}`}>
                            {transaction.transactionType === TransactionType.DEBIT ? '+' : '-'}
                            RWF {Number(transaction.totalAmount).toLocaleString()}
                          </p>
                          {Number(transaction.taxAmount) > 0 && (
                            <p className="text-xs text-muted-foreground mt-1">
                              Tax: RWF {Number(transaction.taxAmount).toLocaleString()} ({transaction.taxRate}%)
                            </p>
                          )}
                          <p className="text-xs text-muted-foreground mt-1">
                            {transaction.paymentMethod.replace(/_/g, ' ')}
                          </p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* RECURRING TRANSACTIONS TAB */}
        <TabsContent value="recurring">
          <Card>
            <CardHeader>
              <CardTitle>Recurring Transactions</CardTitle>
            </CardHeader>
            <CardContent>
              {recurringTransactions.length === 0 ? (
                <p className="text-center py-8 text-muted-foreground">No recurring transactions found</p>
              ) : (
                <div className="space-y-4">
                  {recurringTransactions.map((transaction) => (
                    <div
                      key={transaction.id}
                      className="p-4 border rounded-lg"
                    >
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                            <Badge>
                              <Repeat className="h-3 w-3 mr-1" />
                              {transaction.recurringFrequency}
                            </Badge>
                            <Badge variant={transaction.transactionType === TransactionType.DEBIT ? "default" : "destructive"}>
                              {transaction.transactionType === TransactionType.DEBIT ? "Income" : "Expense"}
                            </Badge>
                          </div>
                          <h4 className="font-medium">{transaction.description}</h4>
                          <p className="text-sm text-muted-foreground mt-1">
                            {transaction.categoryPath || transaction.category?.name}
                          </p>
                        </div>
                        <div className="text-right space-y-2">
                          <p className="text-lg font-bold">
                            RWF {Number(transaction.totalAmount).toLocaleString()}
                          </p>
                          <Button
                            size="sm"
                            onClick={() => executeMutation.mutate(transaction.id)}
                            disabled={executeMutation.isPending}
                          >
                            Execute Now
                          </Button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  )
}